	private startVideoScaleLoop(): void {
		if (this.videoScaleRafId !== null) return;

		const step = () => {
			const scrollTop = window.scrollY || window.document.documentElement.scrollTop;
			this.targetVideoScale = Math.max(
				this.videoScaleMin,
				Math.min(this.videoScaleMax, this.videoScaleMin + scrollTop / 1000),
			);
			this.currentVideoScale += (this.targetVideoScale - this.currentVideoScale) * 0.12;
			this.applyVideoScale(this.currentVideoScale);

			this.videoScaleRafId = requestAnimationFrame(step);
		};

		this.videoScaleRafId = requestAnimationFrame(step);
	}

	private applyVideoScale(scale: number): void {
		this.videoWrapper?.nativeElement.style.setProperty('--video-scale', scale.toFixed(4));
	}

