	private backgroundVideosWerePlaying = {
	desktop: false,
	mobile: false
};
playVideoInModal(): void {
	if (!isPlatformBrowser(this.platformId)) return;

	const desktopVideo = this.desktopVideo?.nativeElement;
	const mobileVideo = this.mobileVideo?.nativeElement;

	const modalDesktopVideo = this.modalDesktopVideo?.nativeElement;
	const modalMobileVideo = this.modalMobileVideo?.nativeElement;

	const modal = this.videoModal?.nativeElement;

	if (!modal || !modalDesktopVideo || !modalMobileVideo) return;

	// Remember background state
	this.backgroundVideosWerePlaying.desktop =
		!!desktopVideo && !desktopVideo.paused;

	this.backgroundVideosWerePlaying.mobile =
		!!mobileVideo && !mobileVideo.paused;

	// ❌ STOP HERO VIDEOS
	desktopVideo?.pause();
	mobileVideo?.pause();

	// Open modal
	modal.classList.add('is-open');
	this.isVideoModalOpen = true;

	// Determine screen
	const isDesktop = window.matchMedia('(min-width: 768px)').matches;

	// ✅ ONLY MODAL VIDEO PLAYS
	const activeModalVideo = isDesktop
		? modalDesktopVideo
		: modalMobileVideo;

	const inactiveModalVideo = isDesktop
		? modalMobileVideo
		: modalDesktopVideo;

	// Stop other modal video
	inactiveModalVideo.pause();
	inactiveModalVideo.currentTime = 0;

	// Start modal video
	activeModalVideo.currentTime = 0;
	activeModalVideo.muted = false;
	activeModalVideo.volume = 1;

	activeModalVideo.play().catch((err) => {
		console.error('Modal video play error:', err);
	});
}
closeVideoModal(): void {
	if (!isPlatformBrowser(this.platformId)) return;

	const desktopVideo = this.desktopVideo?.nativeElement;
	const mobileVideo = this.mobileVideo?.nativeElement;

	const modalDesktopVideo = this.modalDesktopVideo?.nativeElement;
	const modalMobileVideo = this.modalMobileVideo?.nativeElement;

	const modal = this.videoModal?.nativeElement;

	if (!modal) return;

	// ❌ STOP MODAL VIDEOS
	modalDesktopVideo?.pause();
	modalMobileVideo?.pause();

	if (modalDesktopVideo) {
		modalDesktopVideo.currentTime = 0;
	}

	if (modalMobileVideo) {
		modalMobileVideo.currentTime = 0;
	}

	// Close modal
	modal.classList.remove('is-open');
	this.isVideoModalOpen = false;

	// ✅ Resume hero video only if it was playing before
	if (this.backgroundVideosWerePlaying.desktop) {
		desktopVideo?.play().catch(() => {});
	}

	if (this.backgroundVideosWerePlaying.mobile) {
		mobileVideo?.play().catch(() => {});
	}

	this.backgroundVideosWerePlaying.desktop = false;
	this.backgroundVideosWerePlaying.mobile = false;
}

	// The video shrinking back from fullscreen is a layout change, not real
	// pointer movement, so no mouseenter/mouseleave fires for it — re-derive
	// hover state from the last known real cursor position instead.
	private resyncVideoHoverState(video: HTMLVideoElement): void {
		const rect = video.getBoundingClientRect();
		const isOverVideo =
			this.lastMouseClientX >= rect.left &&
			this.lastMouseClientX <= rect.right &&
			this.lastMouseClientY >= rect.top &&
			this.lastMouseClientY <= rect.bottom;

		const syntheticEvent = {
			clientX: this.lastMouseClientX,
			clientY: this.lastMouseClientY,
		} as MouseEvent;
		if (isOverVideo) {
			this.handleVideoMouseEnter(syntheticEvent);
		} else {
			this.handleVideoMouseLeave();
		}
	}
