	private setupDeferredSectionObservers(): void {
		if (!isPlatformBrowser(this.platformId)) return;

		if (!('IntersectionObserver' in window)) {
			this.loadTestimonialsSection();
			this.loadFaqSection();
			return;
		}

		this.observeDeferredSection(this.testimonialsTrigger?.nativeElement, () => {
			this.loadTestimonialsSection();
		});
		this.observeDeferredSection(this.faqTrigger?.nativeElement, () => {
			this.loadFaqSection();
		});
	}

	private observeDeferredSection(
		element: HTMLDivElement | undefined,
		onIntersect: () => void,
	): void {
		if (!element) return;

		const observer = new IntersectionObserver(
			(entries) => {
				if (!entries.some((entry) => entry.isIntersecting)) {
					return;
				}

				observer.disconnect();
				onIntersect();
			},
			{ rootMargin: '300px 0px' },
		);

		observer.observe(element);
		this.deferredSectionObservers.push(observer);
	}

	private loadTestimonialsSection(): void {
		if (this.shouldLoadTestimonials) return;

		this.shouldLoadTestimonials = true;
		this.getTestimonialsData();
		this.cdr.detectChanges();
	}

	private loadFaqSection(): void {
		if (this.shouldLoadFaqs) return;

		this.shouldLoadFaqs = true;
		this.getFaqsData();
		this.cdr.detectChanges();
	}

